#include <vector>
#include <algorithm>

class Solution {
public:
    long long minSwapsToPartition(std::vector<int>& nums) {
        long long s0 = 0, ones = 0;
        for (int x : nums) {
            if (x == 1) ones++;
            else s0 += ones;
        }
        long long s1 = 0, zeros = 0;
        for (int x : nums) {
            if (x == 0) zeros++;
            else s1 += zeros;
        }
        return std::min(s0, s1);
    }
};

